info("Test that a previously accessed folder didn't change its flags");

const dbFolder = folderSource.msgDatabase.dBFolderInfo;
Assert.equal(
  dbFolder.viewFlags,
  Ci.nsMsgViewFlagsType.kThreadedDisplay,
  "viewFlags should remain threaded"
);
Assert.equal(
  dbFolder.sortType,
  Ci.nsMsgViewSortType.byDate,
  "sortType should remain byDate"
);
Assert.equal(
  dbFolder.sortOrder,
  Ci.nsMsgViewSortOrder.descending,
  "sortOrder should remain descending"
);

folder.msgDatabase.dBFolderInfo.viewFlags = Services.prefs.getIntPref(
  "mailnews.default_view_flags"
);
folder.msgDatabase.dBFolderInfo.sortType = Services.prefs.getIntPref(
  "mailnews.default_sort_type"
);
folder.msgDatabase.dBFolderInfo.sortOrder = Services.prefs.getIntPref(
  "mailnews.default_sort_order"
);
// Null out to avoid memory bloat.
folder.msgDatabase = null;
